@prefix acl: <http://www.w3.org/ns/auth/acl#>.
@prefix acp: <http://www.w3.org/ns/solid/acp#>.

<#acr>
    a acp:AccessControlResource;
    acp:resource <http://localhost:3101/alice/ch3/20260928T093809.512Z-non-cooperating-r08/>;
    acp:accessControl <#readers>.

<#readers>
    a acp:AccessControl;
    acp:apply [
        a acp:Policy;
        acp:allow acl:Read;
        acp:anyOf
        [ a acp:Matcher; acp:agent <http://localhost:3101/appr/profile/card#me> ],
        [ a acp:Matcher; acp:agent <http://localhost:3101/bob/profile/card#me> ]
    ].

